"""Planner-based approach for PR2Blocked.

An internal copy of the environment (same dynamics) is synced to the observed
state; plans are searched and verified by simulation, then replayed.
"""
from __future__ import annotations

import math
import time

import numpy as np

STEP = 0.2


def _wrap(a):
    return (a + np.pi) % (2 * np.pi) - np.pi


def _quat_to_R(q):
    x, y, z, w = q
    return np.array([
        [1 - 2 * (y * y + z * z), 2 * (x * y - z * w), 2 * (x * z + y * w)],
        [2 * (x * y + z * w), 1 - 2 * (x * x + z * z), 2 * (y * z - x * w)],
        [2 * (x * z - y * w), 2 * (y * z + x * w), 1 - 2 * (x * x + y * y)],
    ])


def _Rz(a):
    c, s = math.cos(a), math.sin(a)
    return np.array([[c, -s, 0], [s, c, 0], [0, 0, 1.0]])


def _Ry(b):
    c, s = math.cos(b), math.sin(b)
    return np.array([[c, 0, s], [0, 1, 0], [-s, 0, c]])


def _rot_err(Rt, Rc):
    """Orientation error vector (world frame), small-angle robust."""
    return 0.5 * (np.cross(Rc[:, 0], Rt[:, 0]) + np.cross(Rc[:, 1], Rt[:, 1])
                  + np.cross(Rc[:, 2], Rt[:, 2]))


class Sim:
    def __init__(self, num_spares):
        from robocode.environments.pr2_tamp_blocked_env import PR2BlockedEnv

        self.env = PR2BlockedEnv(num_spares=num_spares)
        self.env.reset(seed=0)
        self.n = num_spares
        e = self.env
        from robocode.environments import ss_pybullet as ssp

        self.ssp = ssp
        with e.client():
            self.arm_limits = [ssp.get_joint_limits(e.robot, j) for j in e.arm_joints] \
                if hasattr(ssp, "get_joint_limits") else None
        self.circ = np.array([False, False, True, False, False, False, False, True, False, True])
        lo = np.array([-5, -5, -np.pi, -0.715, -0.524, -0.8, -2.321, -np.pi, -2.094, -np.pi])
        hi = np.array([5, 5, np.pi, 2.285, 1.396, 3.9, 0.0, np.pi, 0.0, np.pi])
        try:
            lo = np.array(list(e._base_limits[0]) + list(e._arm_limits[0]), dtype=float)
            hi = np.array(list(e._base_limits[1]) + list(e._arm_limits[1]), dtype=float)
        except Exception:
            pass
        self.lo, self.hi = lo, hi

    # ---------------------------------------------------------------- sync
    def flat_from_state(self, state):
        names = state.get_object_names() if hasattr(state, "get_object_names") else None
        get = state.get

        def obj(name):
            return state.get_object_from_name(name)

        rf = ["base_x", "base_y", "base_rot"] + [f"joint_{i}" for i in range(1, 8)] + \
            ["gripper_opening", "grasp_active"] + \
            [f"grasp_tf_{f}" for f in ("x", "y", "z", "qx", "qy", "qz", "qw")]
        sf = ["pose_x", "pose_y", "pose_z", "pose_qx", "pose_qy", "pose_qz", "pose_qw",
              "half_extent_x", "half_extent_y", "half_extent_z"]
        bf = ["pose_x", "pose_y", "pose_z", "pose_qx", "pose_qy", "pose_qz", "pose_qw",
              "grasp_active", "half_extent_x", "half_extent_y", "half_extent_z"]
        v = []
        r = obj("robot")
        v += [get(r, f) for f in rf]
        for s in ("near_table", "far_table", "plate"):
            o = obj(s)
            v += [get(o, f) for f in sf]
        for i in range(self.n + 1):
            o = obj(f"green{i}")
            v += [get(o, f) for f in bf]
        o = obj("blocker")
        v += [get(o, f) for f in bf]
        return np.array(v, dtype=np.float32)

    def sync(self, state, set_walls=False):
        flat = self.flat_from_state(state)
        e = self.env
        e.set_state(flat)
        if set_walls:
            ssp = self.ssp
            with e.client():
                pen_now = ssp.get_pose(e.penned)
                pen0 = e._initial_poses[e.penned]
                T = ssp.multiply(pen_now, ssp.invert(pen0))
                for body, pose in e._initial_wall_poses.items():
                    ssp.set_pose(body, ssp.multiply(T, pose))
        return flat

    # ---------------------------------------------------------------- kinematics
    def set_conf(self, q):
        e = self.env
        ssp = self.ssp
        ssp.set_joint_positions(e.robot, e.base_joints, q[:3])
        ssp.set_joint_positions(e.robot, e.arm_joints, q[3:10])

    def get_conf(self):
        e = self.env
        ssp = self.ssp
        return np.array(list(ssp.get_joint_positions(e.robot, e.base_joints)) +
                        list(ssp.get_joint_positions(e.robot, e.arm_joints)))

    def tool(self, q=None):
        e = self.env
        if q is not None:
            self.set_conf(q)
        p, qt = self.ssp.get_link_pose(e.robot, e.tool_link)
        return np.array(p), _quat_to_R(qt)

    def jacobian(self):
        import pybullet as p
        e = self.env
        cid = e.client_id
        if not hasattr(self, "_mj"):
            from pybullet_tools.utils import get_movable_joints
            self._mj = list(get_movable_joints(e.robot))
            self._jidx = [self._mj.index(j) for j in list(e.base_joints) + list(e.arm_joints)]
        js = [s[0] for s in p.getJointStates(e.robot, self._mj, physicsClientId=cid)]
        z = [0.0] * len(js)
        lin, ang = p.calculateJacobian(e.robot, e.tool_link, [0, 0, 0], js, z, z,
                                       physicsClientId=cid)
        J = np.vstack([np.array(lin)[:, self._jidx], np.array(ang)[:, self._jidx]])
        return J

    def ik(self, pt, Rt, q0, q_ref=None, iters=150, wbase=1.0, wnull=0.02):
        """Damped least squares IK over base(x,y,theta)+arm. Requires client."""
        q = np.array(q0, dtype=float)
        if q_ref is None:
            q_ref = q.copy()
        eps = 1e-4
        for it in range(iters):
            p, R = self.tool(q)
            ep = pt - p
            er = _rot_err(Rt, R)
            err = np.concatenate([ep, 0.3 * er])
            if np.linalg.norm(ep) < 1e-4 and np.linalg.norm(er) < 2e-3:
                return q, True
            J = self.jacobian()
            J[3:] *= 0.3
            W = np.ones(10)
            W[:3] *= wbase
            JW = J * W
            lam = 0.05
            A = JW @ JW.T + lam ** 2 * np.eye(6)
            dx = JW.T @ np.linalg.solve(A, err)
            dq = W * dx
            # null space toward reference
            N = np.eye(10) - np.linalg.pinv(JW) @ JW
            dn = q_ref - q
            dn[self.circ] = _wrap(dn[self.circ])
            dq += wnull * (W * (N @ dn))
            n = np.max(np.abs(dq))
            if n > 0.3:
                dq *= 0.3 / n
            q = q + dq
            q[self.circ] = _wrap(q[self.circ])
            q = np.clip(q, self.lo, self.hi)
        p, R = self.tool(q)
        ok = np.linalg.norm(pt - p) < 2e-3 and np.linalg.norm(_rot_err(Rt, R)) < 1e-2
        return q, ok


def conf_delta(qa, qb, circ):
    d = np.asarray(qb, dtype=float) - np.asarray(qa, dtype=float)
    d[circ] = _wrap(d[circ])
    return d


def n_steps(qa, qb, circ):
    d = conf_delta(qa, qb, circ)
    return int(math.ceil(np.max(np.abs(d)) / STEP - 1e-6))


# --------------------------------------------------------------------------
# Library of arm configurations (tool pose in base frame); see gen_lib.py
_LIB = None


def _load_lib(sim):
    """Decode the arm library and compute tool pose in base frame by FK."""
    global _LIB
    if _LIB is None:
        import base64
        import zlib
        arm = np.frombuffer(zlib.decompress(base64.b64decode("".join(ARM_B64))),
                            dtype=np.float32).reshape(-1, 7).astype(float)
        e = sim.env
        ssp = sim.ssp
        with e.client():
            saved = sim.get_conf()
            rows = []
            for qa in arm:
                q = np.concatenate([[0.0, 0.0, 0.0], qa])
                p, R = sim.tool(q)
                phi = math.atan2(R[1, 0], R[0, 0])
                beta = math.asin(max(-1.0, min(1.0, -R[2, 0])))
                rows.append(np.concatenate([qa, p, [phi, beta]]))
            sim.set_conf(saved)
        _LIB = np.array(rows)
    return _LIB


def _yaw_of(q):
    x, y, z, w = q
    return math.atan2(2 * (w * z + x * y), 1 - 2 * (y * y + z * z))


class Planner:
    def __init__(self, sim, deadline):
        self.sim = sim
        self.env = sim.env
        self.deadline = deadline
        self.circ = sim.circ

    # ------------------------------------------------------------ helpers
    def interp(self, qa, qb, n):
        d = conf_delta(qa, qb, self.circ)
        out = []
        for k in range(1, n + 1):
            q = np.asarray(qa, dtype=float) + d * k / n
            q[self.circ] = _wrap(q[self.circ])
            out.append(q)
        return out

    def simulate(self, flat, confs, grips):
        """Run sim env from flat state; return (ok, final_flat, terminated)."""
        e = self.env
        e.set_state(flat)
        cur = flat[:10].astype(float)
        term = False
        for q, g in zip(confs, grips):
            d = conf_delta(cur, q, self.circ)
            if np.max(np.abs(d)) > STEP + 1e-6:
                return False, None, False
            a = np.zeros(11, dtype=np.float32)
            a[:10] = np.clip(d, -STEP, STEP)
            a[10] = g
            obs, _, term, _, _ = e.step(a)
            cur = obs[:10].astype(float)
            if np.max(np.abs(conf_delta(cur, q, self.circ))) > 1e-3:
                return False, None, False
            if term:
                break
        return True, e.get_state().copy(), term

    # ------------------------------------------------------------ grasps
    def grasp_candidates(self, q0, block, ox_list=(0.0, 0.01, 0.02, 0.03, 0.04)):
        e = self.env
        ssp = self.sim.ssp
        L = _load_lib(self.sim)
        bp, bq = ssp.get_pose(block)
        B = np.array(bp)
        byaw = _yaw_of(bq)
        arm = L[:, :7]
        T = L[:, 7:10]
        phi = L[:, 10]
        beta = L[:, 11]
        v = T[:, 2] - B[2]
        cands = []
        for k in range(4):
            psi = byaw + k * np.pi / 2
            for ox in ox_list:
                h = (ox - v * np.sin(beta)) / np.cos(beta)
                oz = h * np.sin(beta) - v * np.cos(beta)
                ok = (np.abs(oz) < 0.062) & (np.hypot(ox, oz) < 0.076)
                th = _wrap(psi - phi)
                tx = B[0] - h * np.cos(psi)
                ty = B[1] - h * np.sin(psi)
                bx = tx - (np.cos(th) * T[:, 0] - np.sin(th) * T[:, 1])
                by = ty - (np.sin(th) * T[:, 0] + np.cos(th) * T[:, 1])
                Q = np.column_stack([bx, by, th, arm])
                D = Q - q0[None, :]
                D[:, self.circ] = _wrap(D[:, self.circ])
                ns = np.ceil(np.max(np.abs(D), axis=1) / STEP - 1e-6)
                for i in np.nonzero(ok)[0]:
                    cands.append((ns[i], Q[i]))
        cands.sort(key=lambda c: c[0])
        return cands

    def valid_grasp_conf(self, q, block):
        e = self.env
        self.sim.set_conf(q)
        if e._in_collision():
            return False
        return e._grasp_candidate() == block

    def plan_grasp(self, flat0, block, max_keep=8, extra=(0, 1, 2)):
        """Return list of (n, confs, grips, flat_after) for grasping block."""
        e = self.env
        q0 = flat0[:10].astype(float)
        e.set_state(flat0)
        cands = self.grasp_candidates(q0, block)
        res = []
        for n, q in cands:
            if time.time() > self.deadline or len(res) >= max_keep:
                break
            e.set_state(flat0)
            if not self.valid_grasp_conf(q, block):
                continue
            for ex in extra:
                N = int(n) + ex
                confs = self.interp(q0, q, N)
                grips = [0.0] * (N - 1) + [-1.0]
                ok, flat, _ = self.simulate(flat0, confs, grips)
                if ok and flat[11] > 0.5:
                    res.append((N, confs, grips, flat))
                    break
        return res

    # ------------------------------------------------------------ carry
    def plan_translate_to_plate(self, flat0):
        """Carry the held block onto the plate with base translation only."""
        e = self.env
        ssp = self.sim.ssp
        q0 = flat0[:10].astype(float)
        e.set_state(flat0)
        att = e._attachment
        # lift first: arm-only perturbation that raises the held block
        rng = np.random.default_rng(1)
        best = None
        for _ in range(400):
            q = q0.copy()
            q[3:] += rng.uniform(-STEP, STEP, 7)
            q[self.circ] = _wrap(q[self.circ])
            q = np.clip(q, self.sim.lo, self.sim.hi)
            self.sim.set_conf(q)
            att.assign()
            z = ssp.get_pose(att.child)[0][2]
            if best is None or z > best[0]:
                if not e._in_collision():
                    best = (z, q)
        e.set_state(flat0)
        if best is None:
            return None
        ok, flatL, _ = self.simulate(flat0, [best[1]], [0.0])
        if not ok:
            return None
        res = self._translate(flatL)
        if res is None:
            return None
        return res[0] + 1, [best[1]] + res[1], [0.0] + res[2], res[3]

    def _translate(self, flat0):
        e = self.env
        ssp = self.sim.ssp
        q0 = flat0[:10].astype(float)
        e.set_state(flat0)
        bp = np.array(ssp.get_pose(e._attachment.child)[0])
        c0, s0 = math.cos(q0[2]), math.sin(q0[2])
        d = bp[:2] - q0[:2]
        brel = np.array([c0 * d[0] + s0 * d[1], -s0 * d[0] + c0 * d[1]])
        cands = []
        for k in range(16):
            th = _wrap(q0[2] + k * np.pi / 8)
            c, s_ = math.cos(th), math.sin(th)
            off = np.array([c * brel[0] - s_ * brel[1], s_ * brel[0] + c * brel[1]])
            for tx in (4.5, 4.4, 4.6, 4.3, 4.7):
                for ty in (-0.3, -0.2, -0.4, -0.12, -0.48):
                    base = np.array([tx, ty]) - off
                    if np.any(np.abs(base) > 4.95):
                        continue
                    q = q0.copy()
                    q[:2] = base
                    q[2] = th
                    cands.append((n_steps(q0, q, self.circ), q))
        cands.sort(key=lambda c: c[0])
        for N, q in cands[:60]:
            if time.time() > self.deadline:
                break
            for extra in (0, 2):
                confs = self.interp(q0, q, N + extra)
                grips = [0.0] * (N + extra - 1) + [1.0]
                ok, flat, term = self.simulate(flat0, confs, grips)
                if ok and term:
                    return N + extra, confs, grips, flat
        return None

    def plan_place_on_plate(self, flat0, rng, max_n=6, samples=1500, need_goal=True,
                            region=None, avoid=None):
        e = self.env
        q0 = flat0[:10].astype(float)
        sim = self.sim
        ssp = sim.ssp
        for N in range(1, max_n + 1):
            if time.time() > self.deadline:
                return None
            e.set_state(flat0)
            att = e._attachment
            best = None
            U = rng.uniform(-1, 1, size=(samples, 10)) * STEP * N
            # favour base motions
            for u in U:
                if time.time() > self.deadline:
                    return None
                q = q0 + u
                q[self.circ] = _wrap(q[self.circ])
                q = np.clip(q, sim.lo, sim.hi)
                sim.set_conf(q)
                att.assign()
                bp, bq = ssp.get_pose(att.child)
                # over plate with margin
                if region is None:
                    if not (4.26 < bp[0] < 4.74 and -0.54 < bp[1] < -0.06):
                        continue
                elif not region(bp):
                    continue
                if bp[2] < 0.80:
                    continue
                if e._in_collision():
                    continue
                confs = self.interp(q0, q, N)
                grips = [0.0] * (N - 1) + [1.0]
                ok, flat, term = self.simulate(flat0, confs, grips)
                e.set_state(flat0)
                att = e._attachment
                if ok and (term or (not need_goal and flat[11] < 0.5)):
                    if avoid is None or avoid(flat):
                        return N, confs, grips, flat
        return None


_SIMS = {}


class GeneratedApproach:
    def __init__(self, action_space, observation_space, primitives):
        self.action_space = action_space
        self.observation_space = observation_space
        self.plan = []
        self.idx = 0
        self.replans = 0
        self.circ = np.array([False, False, True, False, False, False, False, True, False, True])

    def _count(self, state):
        n = 0
        for o in state.get_object_names():
            s = str(o)
            if s.startswith("green"):
                n += 1
        return n - 1

    def _get_sim(self, n):
        if n not in _SIMS:
            _SIMS[n] = Sim(n)
        return _SIMS[n]

    def reset(self, state, info):
        self.t0 = time.time()
        self.ep_deadline = self.t0 + 48.0
        self.plan = []
        self.idx = 0
        self.replans = 0
        n = self._count(state)
        self.sim = self._get_sim(n)
        self.flat0 = self.sim.sync(state, set_walls=True)
        with self.sim.env.client():
            try:
                self.plan = self._make_plan(self.flat0)
            except Exception as ex:  # pragma: no cover
                import traceback
                traceback.print_exc()
                self.plan = []
            self.sim.env.set_state(self.flat0)

    def _make_plan(self, flat0):
        sim = self.sim
        e = sim.env
        planner = Planner(sim, min(self.t0 + 35.0, self.ep_deadline))
        rng = np.random.default_rng(0)
        best = None
        grasps = [] if getattr(self, "_force", None) else \
            planner.plan_grasp(flat0, e.penned, max_keep=6)
        for (Ng, confs, grips, flat) in grasps:
            if best is not None and Ng + 1 >= best[0]:
                break
            res = planner.plan_place_on_plate(
                flat, rng, max_n=(best[0] - Ng - 1) if best else 6)
            if res is None:
                continue
            Nc, c2, g2, _ = res
            tot = Ng + Nc
            if best is None or tot < best[0]:
                best = (tot, list(zip(confs, grips)) + list(zip(c2, g2)))
        if best is None:
            best = self._fallback_plans(planner, flat0, rng)
        self.debug = dict(ngrasps=len(grasps), best=None if best is None else best[0],
                          t=time.time() - self.t0)
        return [] if best is None else best[1]

    def _fallback_plans(self, planner, flat0, rng):
        sim = self.sim
        e = sim.env
        ssp = sim.ssp
        planner.deadline = min(self.t0 + 45.0, self.ep_deadline)
        # (a) direct grasp with more slack
        grasps = [] if getattr(self, "_force", None) else planner.plan_grasp(flat0, e.penned, max_keep=20, extra=(0, 1, 2, 4, 6))
        for (Ng, confs, grips, flat) in grasps:
            res = planner.plan_place_on_plate(flat, rng, max_n=8)
            if res is not None:
                return (Ng + res[0], list(zip(confs, grips)) + list(zip(res[1], res[2])))
        # (b) move the blocker out of the way, then take the penned block
        e.set_state(flat0)
        pp = np.array(ssp.get_pose(e.penned)[0])
        bp0 = np.array(ssp.get_pose(e.blocker)[0])

        def region(bp):
            return (4.25 < bp[0] < 4.75 and -0.55 < bp[1] < 0.55
                    and np.hypot(bp[0] - pp[0], bp[1] - pp[1]) > 0.3)

        bgr = [] if getattr(self, "_force", None) == "c" else planner.plan_grasp(flat0, e.blocker, max_keep=6, extra=(0, 1, 2, 4))
        for (N1, c1, g1, f1) in bgr:
            r2 = planner.plan_place_on_plate(f1, rng, max_n=8, need_goal=False, region=region)
            if r2 is None:
                continue
            N2, c2, g2, f2 = r2
            pgr = planner.plan_grasp(f2, e.penned, max_keep=4, extra=(0, 1, 2, 4))
            for (N3, c3, g3, f3) in pgr:
                r4 = planner.plan_place_on_plate(f3, rng, max_n=8)
                if r4 is None:
                    continue
                N4, c4, g4, _ = r4
                plan = (list(zip(c1, g1)) + list(zip(c2, g2)) + list(zip(c3, g3))
                        + list(zip(c4, g4)))
                return (len(plan), plan)
        # (c) spares
        for sp in e.spares:
            grs = planner.plan_grasp(flat0, sp, max_keep=3, extra=(0, 1, 2, 4))
            for (N1, c1, g1, f1) in grs:
                r2 = planner.plan_translate_to_plate(f1)
                if r2 is not None:
                    return (0, list(zip(c1, g1)) + list(zip(r2[1], r2[2])))
        return None

    def _replan(self, state):
        self.t0 = time.time()
        sim = self.sim
        flat = sim.sync(state, set_walls=False)
        e = sim.env
        plan = []
        with e.client():
            try:
                planner = Planner(sim, min(self.t0 + 15.0, self.ep_deadline))
                rng = np.random.default_rng(int(time.time()) % 1000)
                if flat[11] > 0.5:
                    held = e._attachment.child if e._attachment is not None else None
                    if held in e.greens:
                        res = planner.plan_place_on_plate(flat, rng, max_n=6)
                        if res is None:
                            res = planner.plan_translate_to_plate(flat)
                        if res is not None:
                            plan = list(zip(res[1], res[2]))
                    if not plan:
                        # drop whatever is held where it is (open), then replan next step
                        plan = [(flat[:10].astype(float), 1.0)]
                else:
                    plan = self._make_plan(flat)
            except Exception:
                plan = []
            e.set_state(flat)
        self.plan = plan
        self.idx = 0

    def get_action(self, state):
        r = state.get_object_from_name("robot")
        cur = np.array([state.get(r, f) for f in
                        ["base_x", "base_y", "base_rot"] + [f"joint_{i}" for i in range(1, 8)]])
        if self.idx > 0 and self.idx <= len(self.plan) and self.replans < 5:
            exp_q, exp_g = self.plan[self.idx - 1]
            held = state.get(r, "grasp_active") > 0.5
            bad = np.max(np.abs(conf_delta(cur, exp_q, self.circ))) > 1e-2
            if exp_g < -0.5 and not held:
                bad = True
            if exp_g > 0.5 and held:
                bad = True
            if bad or self.idx == len(self.plan):
                self.replans += 1
                self._replan(state)
        elif self.idx >= len(self.plan) and self.replans < 5:
            self.replans += 1
            self._replan(state)
        a = np.zeros(11, dtype=np.float32)
        if self.idx < len(self.plan):
            q, g = self.plan[self.idx]
            self.idx += 1
            d = conf_delta(cur, q, self.circ)
            a[:10] = np.clip(d, -STEP, STEP)
            a[10] = g
        return a


